// src/core/assistant-context/default-assumptions.service.ts
// Assunções padrão - valores que o sistema assume quando não informados

export interface DefaultAssumptions {
  time: {
    event: string; // "19:00"
    description: string; // "Vou considerar sábado às 17h, ok?"
  };
  audience: {
    size: number;
    description: string; // "Vou considerar cerca de 10 pessoas."
  };
  pricing: {
    type: 'free' | 'suggested_range' | 'ask';
    range?: { min: number; max: number };
    description: string;
  };
  occupancy: {
    model: 'table' | 'person' | 'hybrid';
    description: string;
  };
}

class DefaultAssumptionsService {
  /**
   * Determina horário padrão baseado no contexto
   */
  getDefaultTime(context: {
    dayOfWeek?: string;
    timeOfDay?: 'morning' | 'afternoon' | 'evening' | 'night';
    eventType?: string;
  }): { time: string; description: string } {
    const { dayOfWeek, timeOfDay, eventType } = context;

    // Se já tem horário específico, não assume
    if (context.timeOfDay && !['morning', 'afternoon', 'evening', 'night'].includes(context.timeOfDay)) {
      return { time: '', description: '' };
    }

    // Eventos sociais / lazer
    if (eventType === 'social' || eventType === 'leisure' || !eventType) {
      if (timeOfDay === 'morning') {
        return { time: '10:00', description: 'Vou considerar às 10h, ok?' };
      }
      if (timeOfDay === 'afternoon') {
        return { time: '17:00', description: 'Vou considerar às 17h, ok?' };
      }
      if (timeOfDay === 'evening' || timeOfDay === 'night') {
        return { time: '19:00', description: 'Vou considerar às 19h, ok?' };
      }

      // Por dia da semana
      if (dayOfWeek === 'friday' || dayOfWeek === 'sexta') {
        return { time: '20:00', description: 'Vou considerar sexta às 20h, ok?' };
      }
      if (dayOfWeek === 'saturday' || dayOfWeek === 'sábado') {
        return { time: '17:00', description: 'Vou considerar sábado às 17h, ok?' };
      }
      if (dayOfWeek === 'sunday' || dayOfWeek === 'domingo') {
        return { time: '12:00', description: 'Vou considerar domingo ao meio-dia, ok?' };
      }

      // Padrão para "hoje"
      return { time: '19:00', description: 'Vou considerar às 19h, ok?' };
    }

    // Almoço / jantar
    if (timeOfDay === 'morning' || eventType?.includes('almoço')) {
      return { time: '12:00', description: 'Vou considerar ao meio-dia, ok?' };
    }
    if (eventType?.includes('jantar')) {
      return { time: '19:00', description: 'Vou considerar às 19h, ok?' };
    }

    // Padrão geral
    return { time: '19:00', description: 'Vou considerar às 19h, ok?' };
  }

  /**
   * Determina tamanho de público padrão baseado no contexto
   */
  getDefaultAudience(context: {
    venueType?: string;
    eventType?: string;
    location?: string;
  }): { size: number; description: string } {
    const { venueType, eventType, location } = context;

    // Casa / churrasco / amigos
    if (
      venueType === 'home' ||
      venueType === 'casa' ||
      eventType === 'churrasco' ||
      eventType === 'friends' ||
      location?.toLowerCase().includes('casa')
    ) {
      return {
        size: 10,
        description: 'Vou considerar cerca de 10 pessoas. Se for mais ou menos, me avisa.',
      };
    }

    // Restaurante / bar pequeno
    if (venueType === 'restaurant' || venueType === 'bar') {
      if (location?.toLowerCase().includes('pequeno') || eventType === 'intimate') {
        return {
          size: 30,
          description: 'Vou considerar cerca de 30 pessoas. Se quiser ajustar, é só falar.',
        };
      }
      // Restaurante médio
      return {
        size: 60,
        description: 'Vou considerar cerca de 60 pessoas. Se quiser ajustar, é só falar.',
      };
    }

    // Show / evento público
    if (eventType === 'show' || eventType === 'public' || venueType === 'venue') {
      return {
        size: 100,
        description: 'Vou considerar cerca de 100 pessoas. Se quiser ajustar, é só falar.',
      };
    }

    // Evento corporativo
    if (eventType === 'corporate' || eventType === 'business') {
      return {
        size: 20,
        description: 'Vou considerar cerca de 20 pessoas. Se quiser ajustar, é só falar.',
      };
    }

    // Padrão geral (evento social)
    return {
      size: 10,
      description: 'Vou considerar cerca de 10 pessoas. Se for mais ou menos, me avisa.',
    };
  }

  /**
   * Determina modelo de preço padrão
   */
  getDefaultPricing(context: {
    eventType?: string;
    venueType?: string;
    isCompetitive?: boolean;
  }): DefaultAssumptions['pricing'] {
    const { eventType, venueType, isCompetitive } = context;

    // Reserva de mesa
    if (venueType === 'restaurant' || eventType === 'reservation') {
      return {
        type: 'free',
        description: 'Reserva gratuita.',
      };
    }

    // Evento informal
    if (eventType === 'social' || eventType === 'friends' || eventType === 'casual') {
      return {
        type: 'free',
        description: 'Evento gratuito.',
      };
    }

    // Show / atração
    if (eventType === 'show' || eventType === 'concert' || eventType === 'entertainment') {
      if (venueType === 'bar' || venueType === 'local') {
        return {
          type: 'suggested_range',
          range: { min: 20, max: 40 },
          description: 'Sugestão de ingresso: R$ 20 a R$ 40. Você define o valor final.',
        };
      }
      return {
        type: 'suggested_range',
        range: { min: 40, max: 80 },
        description: 'Sugestão de ingresso: R$ 40 a R$ 80. Você define o valor final.',
      };
    }

    // Evento disputado
    if (isCompetitive) {
      return {
        type: 'ask',
        description: 'Qual valor você quer cobrar?',
      };
    }

    // Padrão: gratuito
    return {
      type: 'free',
      description: 'Evento gratuito.',
    };
  }

  /**
   * Determina modelo de ocupação
   */
  getDefaultOccupancy(context: {
    venueType?: string;
    eventType?: string;
  }): { model: 'table' | 'person' | 'hybrid'; description: string } {
    const { venueType, eventType } = context;

    // Restaurante
    if (venueType === 'restaurant') {
      return {
        model: 'table',
        description: 'Vou organizar por mesas.',
      };
    }

    // Bar sem mesa / Show
    if (venueType === 'bar' || eventType === 'show' || eventType === 'concert') {
      return {
        model: 'person',
        description: 'Vou organizar por pessoa em pé.',
      };
    }

    // Evento misto
    if (eventType === 'mixed' || eventType === 'hybrid') {
      return {
        model: 'hybrid',
        description: 'Vou organizar de forma mista (mesas e áreas em pé).',
      };
    }

    // Padrão: por pessoa
    return {
      model: 'person',
      description: 'Vou organizar por pessoa.',
    };
  }

  /**
   * Gera resumo de assunções para o prompt da IA
   */
  generateAssumptionsSummary(context: {
    dayOfWeek?: string;
    timeOfDay?: string;
    venueType?: string;
    eventType?: string;
    location?: string;
    isCompetitive?: boolean;
  }): string {
    const time = this.getDefaultTime({
      dayOfWeek: context.dayOfWeek,
      timeOfDay: context.timeOfDay as any,
      eventType: context.eventType,
    });

    const audience = this.getDefaultAudience({
      venueType: context.venueType,
      eventType: context.eventType,
      location: context.location,
    });

    const pricing = this.getDefaultPricing({
      eventType: context.eventType,
      venueType: context.venueType,
      isCompetitive: context.isCompetitive,
    });

    const occupancy = this.getDefaultOccupancy({
      venueType: context.venueType,
      eventType: context.eventType,
    });

    const parts: string[] = [];

    if (time.time) {
      parts.push(`Horário: ${time.description}`);
    }

    if (audience.size <= 50) {
      parts.push(`Público: ${audience.description}`);
    }

    if (pricing.type === 'free') {
      parts.push(`Preço: ${pricing.description}`);
    } else if (pricing.type === 'suggested_range' && pricing.range) {
      parts.push(`Preço: ${pricing.description}`);
    }

    if (occupancy.model) {
      parts.push(`Organização: ${occupancy.description}`);
    }

    return parts.length > 0
      ? `\n\nAssunções padrão (use quando não informado):\n${parts.join('\n')}`
      : '';
  }
}

export const defaultAssumptionsService = new DefaultAssumptionsService();


























